spec.expr:
sum by(uri, method) (
  rate(http_server_requests_seconds_count{
    method!~"GET|OPTIONS|HEAD",
    namespace=~"$namespace",
    uri!~"^/actuator/health(/.*)?$|^/actuator/prometheus$|.*/mcp.*",
    uri!~".*/search.*|.*/statistics.*",
  }[$__rate_interval]) != 0
)

max by (exporter, pod, partition) (
    zeebe_rdbms_exporter_replication_pending_positions{
      cluster=~"$cluster",
      namespace=~"$namespace",
      partition=~"$partition"}
)

max by (exporter, pod, partition) (
    zeebe_rdbms_exporter_replication_lag_ms{
      cluster=~"$cluster",
      namespace=~"$namespace",
      partition=~"$partition"}
)

max by (exporter, pod, partition) (
    zeebe_rdbms_exporter_replication_connected_replicas{
      cluster=~"$cluster",
      namespace=~"$namespace",
      partition=~"$partition"}
)
